def solution(n, info):
    def calculate_score(ryan):
        ryan_score = 0
        apeach_score = 0
        for i in range(11):
            if ryan[i] > info[i]:
                ryan_score += 10 - i
            elif info[i] > 0:
                apeach_score += 10 - i
        return ryan_score - apeach_score

    max_score = 0
    answer = []

    # 1부터 11까지의 과녁 개수
    for i in range(1, 12):  
        for combo in combinations(range(11), i):
            ryan = [0] * 11
            left = n
            for idx in combo:
                if left > info[idx]:
                    ryan[idx] = info[idx] + 1
                    left -= ryan[idx]
                if left <= 0:
                    break
            if left > 0:
                ryan[10] += left  # 남은 화살은 모두 0점에 쏘기

            score = calculate_score(ryan)
            if score > max_score:
                max_score = score
                answer = ryan
            elif score == max_score and ryan[::-1] > answer[::-1]:
                answer = ryan

    return answer if max_score > 0 else [-1]

def solution(orders, course):
    result = []
    for c in course:
        count = {}
        for order in orders:
            for o in combinations(order , c):
                key = ''.join(sorted(o))
                count.setdefault(key, 0)
                count[key] += 1
        if len(count.keys()) == 0:
            break
        max_count = count[max(count, key=count.get)]
        if max_count > 1:
            for key in count.keys():
                if count[key] == max_count:
                    result.append(key)
    return sorted(result)

def solution(rows, columns, queries):
    answer = []
    space=[[0]*columns for _ in range(rows)]
    cnt=1
    for i in range(rows):
        for j in range(columns):
            space[i][j]=cnt
            cnt+=1
    for query in queries:
        r1,c1,r2,c2=query
        r1,c1,r2,c2=r1-1,c1-1,r2-1,c2-1

        queue=deque()
        for r in range(c1,c2+1):
            queue.append(space[r1][r])
        for c in range(r1+1,r2):
            queue.append(space[c][c2])
        for r in range(c1,c2+1)[::-1]:
            queue.append(space[r2][r])
        for c in range(r1+1,r2)[::-1]:
            queue.append(space[c][c1])

        queue.rotate(1)
        answer.append(min(queue))

        for r in range(c1,c2+1):
            space[r1][r]=queue.popleft()
        for c in range(r1+1,r2):
            space[c][c2]=queue.popleft()
        for r in range(c1,c2+1)[::-1]:
            space[r2][r]=queue.popleft()
        for c in range(r1+1,r2)[::-1]:
            space[c][c1]=queue.popleft()

    return answer

