    for i in range(n):
        for j in range(n):
            if i==j:
                continue
            else:
                if graph[i][j]>0:
                    dic[friends[i]][0]+=graph[i][j]
                    dic[friends[j]][1]+=graph[i][j]

    ##선물지수까지 체크
